import{_ as t,o as s,c as n,a6 as r}from"./chunks/framework.CCKCzdWs.js";const i="/screenshots/vscode-testing.png",g=JSON.parse(`{"title":"Runs from the editor","description":"Run Playwright tests from VS Code or a JetBrains IDE and follow the run in the status bar: the editor reads its results within a second of its end, lays them over the latest CI run's failures, and says when a run never reached the instance.","frontmatter":{"title":"Runs from the editor","description":"Run Playwright tests from VS Code or a JetBrains IDE and follow the run in the status bar: the editor reads its results within a second of its end, lays them over the latest CI run's failures, and says when a run never reached the instance.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-runs.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-runs.html"}],["meta",{"property":"og:title","content":"Runs from the editor | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Run Playwright tests from VS Code or a JetBrains IDE and follow the run in the status bar: the editor reads its results within a second of its end, lays them over the latest CI run's failures, and says when a run never reached the instance."}]]},"headers":[],"relativePath":"features/editor-runs.md","filePath":"features/editor-runs.md","lastUpdated":1792865852000}`),o={name:"features/editor-runs.md"};function a(h,e,d,l,c,u){return s(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="runs-from-the-editor" tabindex="-1">Runs from the editor <a class="header-anchor" href="#runs-from-the-editor" aria-label="Permalink to &quot;Runs from the editor&quot;">​</a></h1><p>The <a href="./editors.html">editor extensions</a> run your tests where you edit them, then show what the run changed: its progress in the status bar while it executes, and its results over the latest CI run&#39;s <a href="./editor-failures.html">failures</a> within a second of its end.</p><h2 id="run-tests" tabindex="-1">Run tests <a class="header-anchor" href="#run-tests" aria-label="Permalink to &quot;Run tests&quot;">​</a></h2><ul><li>The lines above a locator line, an application file or a page file (CodeLens in VS Code, Code Vision in a JetBrains IDE) run the tests they name when clicked; those of a server file record its <a href="./editor-coverage.html#refresh-the-marks-with-a-local-run">coverage</a>.</li><li><strong>Piwi: Run the test at the cursor</strong> (<code>Ctrl+Shift+Alt+K</code>, <code>Cmd+Shift+Alt+K</code> on macOS) runs the test whose <code>test(…)</code> call holds the cursor, and <strong>Piwi: Run this spec</strong> the spec&#39;s tests Piwi knows; both in the editor&#39;s context menu of a spec (<strong>Run the Test at the Caret</strong> and <strong>Run This Spec</strong> in a JetBrains IDE). In VS Code, <strong>Run</strong> in the hover of a test&#39;s line runs that test, and so does <a href="#the-testing-view-vs-code">the Testing view</a>. A test the instance does not know yet, such as one you just <a href="./editor-recording.html#run-it-or-verify-it-three-times">recorded</a>, runs by the line of its <code>test(…)</code> call (<code>npx playwright test tests/checkout.spec.ts:42</code>), with or without an instance. Both save the spec first.</li><li><strong>Piwi: Verify the test at the cursor ×3</strong> (<strong>Verify the Test at the Caret ×3</strong>) runs that test three times, without retries and without the breakpoints (<code>--repeat-each=3 --retries=0</code>), and says how many of the runs passed: <a href="#when-your-run-ends">When your run ends</a>.</li><li><strong>Piwi: Run the tests that reach this file</strong> runs every test reaching the active file through <a href="/features/code-reach.html">code reach</a>; also in the editor&#39;s context menu.</li><li><strong>Piwi: Run selection…</strong> runs a saved <a href="/features/test-selection.html">selection</a>.</li></ul><p>The command, <code>npx playwright test</code> with the arguments <code>piwi run</code> would pass, runs from the Playwright config&#39;s folder: as a task in VS Code, in a terminal of its own (<strong>Tasks: Rerun Last Task</strong> starts it again), in the Run tool window in a JetBrains IDE (<strong>Rerun</strong> starts it again), or in the IDE&#39;s Playwright runner (test tree, Debug, <strong>Rerun Failed Tests</strong>), a choice of <strong>Settings → Tools → Piwi</strong>. It sets <code>PIWI_ORIGIN=editor</code> and its own <code>PIWI_ORIGIN_REF</code> (<a href="/reference/test-metadata.html#run-origin">run origin</a>), by which the editor finds its run. Breakpoints pause it in the browser, with Piwi&#39;s picker one click away: <a href="./editor-breakpoints.html">Breakpoints in the browser</a>.</p><h2 id="the-testing-view-vs-code" tabindex="-1">The Testing view (VS Code) <a class="header-anchor" href="#the-testing-view-vs-code" aria-label="Permalink to &quot;The Testing view (VS Code)&quot;">​</a></h2><p>VS Code&#39;s Testing view lists Piwi&#39;s tests: the specs your instance knows, as they stand in the editor, under their folders and <code>test.describe</code> blocks, each test with its latest result, and for a failure why and where it failed (<strong>Peek Error</strong>). The results are published as a test run (<code>Piwi: run #120 on main</code>) when the latest run, its baseline or the runs laid over it change, and a run in progress is a test run of its own, each test shown as it begins and ends. The view&#39;s gutter shows each test&#39;s result in place of Piwi&#39;s icon; the line keeps Piwi&#39;s hover.</p><figure><img src="'+i+'" alt="VS Code: the Testing view lists the spec&#39;s tests with their latest results, and a failing test&#39;s error is peeked at its line in the spec"><figcaption>The Testing view with the latest run&#39;s results, and why <strong>pays by card</strong> failed, at its line.</figcaption></figure><p><strong>Run with Piwi</strong>, the view&#39;s run profile, runs the tests you pick as the commands above do, one command per Playwright config with your breakpoints, and <strong>Verify ×3 with Piwi</strong> runs them three times. A test the run gave Piwi no result for, such as one the instance does not know yet, passes when the command exited with 0 and is an error otherwise. The view shows results; it does not discover tests nor debug them: a spec the instance has not seen joins the tree once you open it. The <code>piwi.testExplorer</code> setting turns the view&#39;s Piwi tests off.</p><h2 id="re-run-the-failing-tests" tabindex="-1">Re-run the failing tests <a class="header-anchor" href="#re-run-the-failing-tests" aria-label="Permalink to &quot;Re-run the failing tests&quot;">​</a></h2><p><strong>Piwi: Re-run the failing tests</strong> (<code>Ctrl+Shift+Alt+F</code>, <code>Cmd+Shift+Alt+F</code> on macOS; <strong>Tools → Piwi → Re-run the Failing Tests</strong>) runs every test still failing, or edited since its run, one command per Playwright config, or those of one config from its node in the <a href="./editor-failures.html#the-failures-view">failures view</a>; when none fails, it says so.</p><h2 id="after-a-run" tabindex="-1">After a run <a class="header-anchor" href="#after-a-run" aria-label="Permalink to &quot;After a run&quot;">​</a></h2><p>The editor listens to the instance&#39;s event stream: within a second of a run of the project ending, it reads the branch&#39;s latest run and its failures again, and every five minutes with the stream, every minute without. A checkout or a commit is noticed within seconds: the editor reads the branch&#39;s latest run again, and compares your application files with the new <code>HEAD</code>.</p><p>A run started from the editor is its own wherever it runs: the status bar follows it, the gutter shows each test as running, then its result, and its failures read <em>your run #124</em> once it ends. When the command ends and no run on the instance carries its ref, the editor says so: <code>The run ended (exit code 1) but did not reach https://piwi.example.com: is the Piwi reporter in the Playwright config?</code> The editor learns the command&#39;s end and its exit code from the process it started, in every shell, a rerun included.</p><h2 id="when-your-run-ends" tabindex="-1">When your run ends <a class="header-anchor" href="#when-your-run-ends" aria-label="Permalink to &quot;When your run ends&quot;">​</a></h2><p>Once a run you started from the editor ends and the editor has read it, a notification (a balloon in a JetBrains IDE) says what it changed: <code>Piwi: run #124 · 1 of 3 CI failures fixed, 2 still failing (login.spec.ts › logs in, checkout.spec.ts › pays)</code>, then the tests it failed that were not failing before. It offers <strong>Open the failures</strong>, <strong>Open in dashboard</strong> and, when something fails, <strong>Re-run failing</strong>. The <code>piwi.runNotifications</code> setting (<strong>Settings → Tools → Piwi</strong> in a JetBrains IDE) shows it always, only when something fails, or never.</p><p>A verification (<strong>Verify ×3</strong>) says how many of its runs passed instead, whatever the setting: <code>Piwi: run #124 · Passed 3 of 3</code>, or <code>Failed 1 of 3</code>. Each run is a result of its own on the instance, and the editor counts them from the results the run streams as it executes; when it missed some, a failing verification says <code>Failed at least 1 of 3</code>. When its run never reached an instance, the exit code says it: <code>Passed 3 of 3: tests/checkout.spec.ts:42</code>, or <code>Failed at least 1 of 3: tests/checkout.spec.ts:42 (exit code 1)</code>.</p><h2 id="the-status-bar" tabindex="-1">The status bar <a class="header-anchor" href="#the-status-bar" aria-label="Permalink to &quot;The status bar&quot;">​</a></h2><p>The latest complete run on the branch: how many tests passed, failed and were flaky, or what still fails and what your local runs fixed (<code>2 failing · 1 fixed locally</code>). While a run started from this editor, or another run of the branch, is in progress, the item counts it instead (<code>4/9 · 1 failing · your run</code>) and returns to the latest run when it ends.</p><p>With several Playwright configs, the item speaks for the config of the file you are editing, the deepest config folder that holds it, and follows you from file to file; outside every config folder, it shows the first connected config. Its tooltip names the config (<code>The active file&#39;s Playwright config, in apps/admin (one of 3)</code>), then holds the run&#39;s counts, the baseline, your local runs since, the run in progress, and when the run was read (<code>Updated 12 s ago · live</code> while the event stream is connected, <code>· read every minute</code> without it).</p><p>In VS Code, a click reads the latest run and its failures again (<strong>Piwi: Refresh the latest run</strong>), without the indexes <strong>Piwi: Refresh</strong> fetches, and the tooltip ends with <strong>Open run #120</strong>, <strong>Open in dashboard</strong>, <strong>Compare with…</strong> and <strong>Connect</strong>. When the extension is not connected, the item says why, and a click runs <strong>Piwi: Connect</strong>, or retries an <a href="./editor-connection.html#an-unreachable-instance">unreachable instance</a>.</p><p>In a JetBrains IDE, an icon before the text shows the state of the run the item counts (running, failing, passed) or of the connection, and the text takes the theme&#39;s error color while tests of that run fail, a run in progress included. A click opens a menu of the <strong>Tools → Piwi</strong> actions that apply, led by what the item calls for: <strong>Read the Latest Run Again</strong>, <strong>Refresh</strong> for an unreachable instance, <strong>Connect…</strong> while not connected, <strong>Node.js Settings…</strong> when Node.js is missing or too old, or <strong>Go to the Recorded Lines</strong> while a recording runs, with <strong>Pause Recording</strong>, <strong>Resume Recording</strong> and <strong>Stop Recording</strong>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-failures.html">Failures in the editor</a>: the failures a run leaves, at their lines and in the failures view.</li><li><a href="./editors.html">Editor extensions</a>: what the editor shows from your suite.</li><li><a href="./editor-connection.html">Editor connection</a>: the instance the editor reads, and its key.</li><li><a href="/features/test-selection.html">Test selection</a>: the saved selections <strong>Run selection…</strong> runs.</li></ul>',24)])])}const w=t(o,[["render",a]]);export{g as __pageData,w as default};
